import { appendFile } from "node:fs/promises";
import type { Database } from "../client";
import { deletionTombstone } from "../schema";

/** What was permanently deleted (ADR 0206). Ids only – never names, content or the deleting user. */
export interface DeletionEntry {
  kind: "workspace" | "project" | "session";
  id: string;
  organizationId: string;
  deletedAt: Date;
}

/** Ids are generated by the app (`prefix_hex`); anything else never reaches the list or the scrub. */
const SAFE_ID = /^[A-Za-z0-9_-]{1,128}$/;

/** One line of the deletion list: `<ISO time> <kind> <id> <organization id>`. */
export function deletionLine(entry: DeletionEntry): string {
  return `${entry.deletedAt.toISOString()} ${entry.kind} ${entry.id} ${entry.organizationId}\n`;
}

/**
 * ADR 0206: records a permanent deletion so a restore of an older backup removes the data again (post-restore scrub).
 * Appends a line to the deletion list outside the database backups (`DELETIONS_LOG`, a mounted volume on the server)
 * and stores a tombstone row. Called once after every purge (#197 project, #198 session, workspace deletion), outside
 * any transaction. Never throws into a purge: a failure is logged without the ids' context and the deletion stands.
 */
export async function recordDeletion(db: Database, entry: DeletionEntry, env: Record<string, string | undefined> = process.env): Promise<void> {
  if (!SAFE_ID.test(entry.id) || !SAFE_ID.test(entry.organizationId)) {
    console.warn(JSON.stringify({ level: "warn", message: "deletion not recorded: unexpected id format", kind: entry.kind }));
    return;
  }
  const path = env.DELETIONS_LOG?.trim();
  if (path) {
    try {
      await appendFile(path, deletionLine(entry), { mode: 0o666 });
    } catch (error) {
      console.warn(
        JSON.stringify({ level: "warn", message: "deletion list not writable", error: error instanceof Error ? error.message.slice(0, 200) : "unknown" }),
      );
    }
  }
  try {
    await db
      .insert(deletionTombstone)
      .values({ kind: entry.kind, entityId: entry.id, organizationId: entry.organizationId, deletedAt: entry.deletedAt })
      .onConflictDoNothing();
  } catch (error) {
    console.warn(
      JSON.stringify({ level: "warn", message: "deletion tombstone not stored", error: error instanceof Error ? error.message.slice(0, 200) : "unknown" }),
    );
  }
}
